import {
  createBilling,
  stripeInboxVerify,
} from "better-supabase/blocks/billing";
import { createWebhookInbox, sqlTransport } from "better-supabase/blocks/queue";

import { postgres } from "@/lib/postgres";

/**
 * Stores each verified Stripe event once; the process route hands it to
 * billing.
 */
export const stripeInbox = createWebhookInbox({
  transport: sqlTransport(postgres.admin),
  source: "stripe",
  verify: stripeInboxVerify(process.env.STRIPE_WEBHOOK_SECRET ?? ""),
});

/**
 * The billing block on the service connection, which links customers and syncs
 * seats.
 */
export const billing = createBilling({
  stripe: { secretKey: process.env.STRIPE_SECRET_KEY ?? "" },
  transport: sqlTransport(postgres.admin),
});

import "server-only";
import { stripeInbox } from "@/lib/stripe";

/** Stripe's webhook endpoint: verifies the signature and stores the event once. */
export const POST = (request: Request): Promise<Response> =>
  stripeInbox.receive(request);

import "server-only";
import { billing, stripeInbox } from "@/lib/stripe";

/**
 * Hands the stored Stripe events to the billing block. Call it from a cron that
 * sends `Authorization: Bearer <CRON_SECRET>`; a failed event stays in the
 * inbox for the next run.
 */
export async function GET(request: Request): Promise<Response> {
  const secret = process.env.CRON_SECRET;

  if (!secret || request.headers.get("authorization") !== `Bearer ${secret}`) {
    return new Response(null, { status: 401 });
  }

  const result = await stripeInbox.process((message) =>
    billing.handleStripeEvent(message.payload).orThrow(),
  );

  return Response.json(result);
}
